E047: 10 CE 04 00     LDS    #$0400          ; stack below $0400
E04B: 1C EF           ANDCC  #$EF            ; unmask IRQ
E04D: B7 40 00        STA    IRQ_ON_SOUND    ; IRQ latch on [$4000]
E050: B7 20 07        STA    WATCHDOG        ; watchdog (odd address) [$2007]

